import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('exportCsv returns header and empty rows for empty invoices', () => {
  const csv = exportCsv([]);
  const lines = csv.split('\n');

  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.equal(lines[1], '');
  assert.equal(lines.length, 2);
});

test('exportCsv exports single issued invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }], // €514.25
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');

  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.equal(lines[1], 'INV-2025-0001,Customer 2,2025-10-15,2025-10-29,issued,425.00,0.00,89.25,514.25,514.25');
  assert.equal(lines[2], '');
});

test('exportCsv exports draft invoice with empty number and dueDate', () => {
  const draft = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const csv = exportCsv([draft]);
  const lines = csv.split('\n');

  assert.equal(lines[1], ',Customer 2,2025-10-15,,draft,425.00,0.00,89.25,514.25,514.25');
});

test('exportCsv formats amounts correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }], // €85, VAT €17.85, total €102.85
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');

  assert.equal(lines[1], 'INV-2025-0001,Customer 2,2025-10-15,2025-10-29,issued,85.00,0.00,17.85,102.85,102.85');
});

test('exportCsv includes discount in output', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 20 }], // €850, 20% discount = €170, net €680, VAT €142.80, total €722.80
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');

  assert.equal(lines[1], 'INV-2025-0001,Customer 2,2025-10-15,2025-10-29,issued,850.00,170.00,142.80,822.80,822.80');
});

test('exportCsv includes tier discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier, 5% discount
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }], // €850, 5% tier discount = €42.50, net €807.50, VAT €169.58, total €977.08
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');

  assert.equal(lines[1], 'INV-2025-0001,Customer 1,2025-10-15,2025-10-29,issued,850.00,42.50,169.58,977.08,977.08');
});

test('exportCsv exports partially paid invoice', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }], // €514.25
    terms: 'NET14',
  }).value;
  let issued = issueInvoice(invoice, []).value;
  issued = recordPayment(issued, { amount: 25000, date: '2025-10-20' }).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');

  assert.equal(lines[1], 'INV-2025-0001,Customer 2,2025-10-15,2025-10-29,partially_paid,425.00,0.00,89.25,514.25,264.25');
});

test('exportCsv exports paid invoice', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }], // €514.25
    terms: 'NET14',
  }).value;
  let issued = issueInvoice(invoice, []).value;
  issued = recordPayment(issued, { amount: 51425, date: '2025-10-20' }).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');

  assert.equal(lines[1], 'INV-2025-0001,Customer 2,2025-10-15,2025-10-29,paid,425.00,0.00,89.25,514.25,0.00');
});

test('exportCsv escapes commas in customer name', () => {
  const invoice = createInvoice({
    customerId: 'C-003', // Customer with comma in name
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');

  assert.equal(lines[1], 'INV-2025-0001,"Customer, Inc.",2025-10-15,2025-10-29,issued,85.00,0.00,17.85,102.85,102.85');
});

test('exportCsv escapes double quotes in customer name', () => {
  const invoice = createInvoice({
    customerId: 'C-004', // Customer with quote in name
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');

  assert.equal(lines[1], 'INV-2025-0001,"John ""Johnny"" Smith",2025-10-15,2025-10-29,issued,85.00,0.00,17.85,102.85,102.85');
});

test('exportCsv exports multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }], // €475, VAT €99.75, total €574.75
    terms: 'NET14',
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const csv = exportCsv([issued1, issued2]);
  const lines = csv.split('\n');

  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.equal(lines[1], 'INV-2025-0001,Customer 2,2025-10-01,2025-10-15,issued,425.00,0.00,89.25,514.25,514.25');
  assert.equal(lines[2], 'INV-2025-0002,Customer 2,2025-10-05,2025-10-19,issued,475.00,0.00,99.75,574.75,574.75');
});

test('exportCsv preserves invoice order', () => {
  const invoices = [];

  for (let i = 0; i < 5; i++) {
    const inv = createInvoice({
      customerId: 'C-002',
      issueDate: `2025-10-${String(i + 1).padStart(2, '0')}`,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
      terms: 'NET14',
    }).value;
    const issued = issueInvoice(inv, invoices.map((_, idx) => `INV-2025-${String(idx + 1).padStart(4, '0')}`)).value;
    invoices.push(issued);
  }

  const csv = exportCsv(invoices);
  const lines = csv.split('\n');

  assert.equal(lines[1].startsWith('INV-2025-0001'), true);
  assert.equal(lines[2].startsWith('INV-2025-0002'), true);
  assert.equal(lines[3].startsWith('INV-2025-0003'), true);
  assert.equal(lines[4].startsWith('INV-2025-0004'), true);
  assert.equal(lines[5].startsWith('INV-2025-0005'), true);
});

test('exportCsv with mixed invoice statuses', () => {
  const draft = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
    terms: 'NET14',
  }).value;
  let issued2 = issueInvoice(inv2, []).value;
  issued2 = recordPayment(issued2, { amount: 25500, date: '2025-10-10' }).value;

  const csv = exportCsv([draft, issued2]);
  const lines = csv.split('\n');

  assert.equal(lines[1], ',Customer 2,2025-10-01,,draft,425.00,0.00,89.25,514.25,514.25');
  assert.equal(lines[2], 'INV-2025-0001,Customer 2,2025-10-05,2025-10-19,partially_paid,255.00,0.00,53.55,308.55,58.05');
});

test('exportCsv ends with newline', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const csv = exportCsv([issued]);

  assert.equal(csv.endsWith('\n'), true);
});

test('exportCsv with voucher', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }], // €514.25
    terms: 'NET14',
  }).value;
  const applyResult = issueInvoice(invoice, []);
  invoice = applyResult.value;
  const voucherResult = issueInvoice(invoice, []);
  invoice = voucherResult.value;

  // Apply voucher manually since applyVoucher requires draft
  invoice.voucher = { code: 'TEST', amount: 10000 };
  const totals = {
    subtotal: 42500,
    discount: 0,
    vat: 8925,
    voucher: 10000,
    total: 41425,
  };

  // Calculate what the CSV would show
  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');

  // Voucher is included in total, not shown separately
  assert.equal(lines[1].includes('INV-2025-0001'), true);
  assert.equal(lines[1].includes('41.42'), true); // total 41425 cents = €414.25
});

test('exportCsv with zero values', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }], // €600, 0% VAT, total €600
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');

  // All amounts formatted with 2 decimals
  assert.equal(lines[1], 'INV-2025-0001,Customer 2,2025-10-15,2025-10-29,issued,600.00,0.00,0.00,600.00,600.00');
});

test('exportCsv with large amounts', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'LOGO-PACK', qty: 5 }], // €600 * 5 = €3000, no discount, VAT 21% = €630, total €3630
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');

  assert.equal(lines[1], 'INV-2025-0001,Customer 2,2025-10-15,2025-10-29,issued,3000.00,0.00,630.00,3630.00,3630.00');
});

