test('exportCsv with voucher', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }], // €514.25
    terms: 'NET14',
  }).value;
  const applyResult = issueInvoice(invoice, []);
  invoice = applyResult.value;
  const voucherResult = issueInvoice(invoice, []);
  invoice = voucherResult.value;

  // Apply voucher manually since applyVoucher requires draft
  invoice.voucher = { code: 'TEST', amount: 10000 };
  const totals = {
    subtotal: 42500,
    discount: 0,
    vat: 8925,
    voucher: 10000,
    total: 41425,
  };

  // Calculate what the CSV would show
  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');

  // Voucher is included in total, not shown separately
  assert.equal(lines[1].includes('INV-2025-0001'), true);
  assert.equal(lines[1].includes('41.42'), true); // total 41425 cents = €414.25
});

