    lines: [{ sku: 'DES-HOUR', qty: 3 }],
    terms: 'NET14',
  }).value;
  let issued2 = issueInvoice(inv2, []).value;
  issued2 = recordPayment(issued2, { amount: 25500, date: '2025-10-10' }).value;

  const csv = exportCsv([draft, issued2]);
  const lines = csv.split('\n');

  assert.equal(lines[1], ',Blue Fern Bakery,2025-10-01,2025-10-31,draft,425.00,0.00,89.25,514.25,514.25');
  assert.equal(lines[2], 'INV-2025-0001,Blue Fern Bakery,2025-10-05,2025-10-19,partially_paid,255.00,0.00,53.55,308.55,53.55');
});

